//! Wider PySCF pins for the k-point range-separated hybrids (dense AFT J/K,
//! `ferric_pbc::rsh`), beyond the cubic a = 4 Bohr / exxdiv ewald / 1x1x1,
//! 1x1x2 rows of `pbc_krsh.rs`: a TRICLINIC cell, `exxdiv = None` as well as
//! ewald, and the non-cubic meshes 1x2x2, 2x1x2 and 2x2x2.
//!
//! Reference: PySCF 2.13 `pbc.dft.KRKS`, AFTDF, UniformGrids 41^3, STO-3G H2
//! in the `TRI_A` lattice with the `H2_ATOMS` geometry, conv_tol 1e-12.
//! Provenance (git SHA, date, versions, per-row runtimes):
//! `testdata/reference/pbc_h2_sto3g_triclinic_krsh.json`, generated by
//! `scripts/gen_pyscf_pbc_krsh_refs.py`.
//!
//! # Tolerance, derived from both sides
//!
//! The agreement is a dense-AFT-vs-AFTDF identity on the same grid (no aux
//! fit), so the bar is `PIN_TOL` = 1e-9 Ha, the bar `pbc_krsh.rs` holds on
//! the cubic rows. The defects this must see: a primitive-cell Madelung
//! constant (the `exxdiv` bookkeeping) moves E by `MIN_DEFECT_SHIFT`, an
//! ewald/none mix-up by the ewald-minus-none pin gap; both are checked below
//! to be >= 1e5 times the bar.

mod common;

use common::*;
use ferric_pbc::dense_aft::ExxDiv;
use ferric_pbc::dft::PeriodicGrid;
use ferric_pbc::hcore::PeriodicHcoreConfig;
use ferric_pbc::kdense_aft::KMutation;
use ferric_pbc::kdft::{solve_krks_on_grid, KRksConfig};
use ferric_pbc::kpts::KPointMesh;
use ferric_pbc::lattice::Cell;

const OMEGA: f64 = 0.8;
const MESH: usize = 41;
const PIN_TOL: f64 = 1e-9;
/// A wrong-Madelung defect must exceed the pin bar by far more than 1e3.
const MIN_DEFECT_SHIFT: f64 = 1e-4;

/// (functional, k-mesh, exxdiv, PySCF E_tot).
type Row = (&'static str, [usize; 3], ExxDiv, f64);

const PINS: [Row; 9] = [
    ("HSE06", [1, 1, 1], ExxDiv::Ewald, -1.425296483046),
    ("HSE06", [1, 1, 1], ExxDiv::None, -1.300717690416),
    (
        "HYB_GGA_XC_CAM_B3LYP",
        [1, 1, 1],
        ExxDiv::Ewald,
        -1.447144967614,
    ),
    (
        "HYB_GGA_XC_CAM_B3LYP",
        [1, 1, 1],
        ExxDiv::None,
        -1.160109365720,
    ),
    ("HSE06", [1, 2, 2], ExxDiv::Ewald, -1.205521003053),
    ("HSE06", [1, 2, 2], ExxDiv::None, -1.155818033624),
    (
        "HYB_GGA_XC_CAM_B3LYP",
        [2, 1, 2],
        ExxDiv::Ewald,
        -1.226833848564,
    ),
    ("HSE06", [2, 2, 2], ExxDiv::Ewald, -1.135136432761),
    (
        "HYB_GGA_XC_CAM_B3LYP",
        [2, 2, 2],
        ExxDiv::None,
        -0.957208908294,
    ),
];

fn tri_h2() -> Cell {
    Cell::new(hydrogens(&H2_ATOMS), TRI_A).expect("triclinic H2 cell")
}

fn energy(f: &str, n: [usize; 3], exxdiv: ExxDiv, mutation: Option<KMutation>) -> f64 {
    let cell = tri_h2();
    let bs = pyscf_sto3g_h();
    let prep = prep_for(&cell, &bs);
    let grid = PeriodicGrid::uniform(&cell, [MESH; 3]).unwrap();
    let mesh = KPointMesh::gamma_centred(&cell, n).unwrap();
    let mut cfg = KRksConfig::new(&cell, exxdiv, f);
    cfg.krhf.hcore = PeriodicHcoreConfig::with_omega(OMEGA);
    cfg.krhf.scf.energy_conv = 1e-12;
    cfg.krhf.scf.grad_conv = 1e-9;
    cfg.krhf.dense.mutation = mutation;
    solve_krks_on_grid(&cell, &prep, None, &mesh, &grid, &cfg)
        .unwrap_or_else(|e| panic!("solve_krks {f} {n:?}: {e}"))
        .scf
        .energy
}

#[test]
fn rsh_krks_triclinic_matches_pinned_pyscf() {
    for (f, n, exxdiv, e_ref) in PINS {
        let e = energy(f, n, exxdiv, None);
        eprintln!(
            "{f} {n:?} {exxdiv:?}: E {e:.12} pyscf {e_ref:.12} dE {:.2e}",
            e - e_ref
        );
        assert!((e - e_ref).abs() < PIN_TOL, "{f} {n:?} {exxdiv:?}");
    }
}

/// The pins distinguish the defects: ewald vs none differ by far more than
/// the bar, and the primitive-cell Madelung (ewald, 1x2x2) leaves the pin by
/// more than `MIN_DEFECT_SHIFT`.
#[test]
fn rsh_triclinic_pins_see_the_exxdiv_defects() {
    let (f, n, _, e_ewald) = PINS[4];
    let e_none = PINS[5].3;
    assert!((e_ewald - e_none).abs() > 1e5 * PIN_TOL);
    let e = energy(f, n, ExxDiv::Ewald, Some(KMutation::PrimitiveMadelung));
    eprintln!(
        "PrimitiveMadelung HSE06 {n:?}: dE vs pin {:.2e}",
        e - e_ewald
    );
    assert!((e - e_ewald).abs() > MIN_DEFECT_SHIFT);
    let e = energy(f, n, ExxDiv::Ewald, Some(KMutation::KernelAtG));
    eprintln!("KernelAtG HSE06 {n:?}: dE vs pin {:.2e}", e - e_ewald);
    assert!((e - e_ewald).abs() > MIN_DEFECT_SHIFT);
}
